function itemImg(i){return i.img||imageMap[i.name]||icons[i.name]||''}function casePic(c){if(c.name==='Kilowatt Case')return `<img src="${imageMap[c.name]}" alt="Kilowatt Case">`;return boxArt(c.color,c.id.replace(/\W/g,''))}function caseLoot(c){let names=casePools[c.name]||skins.filter(x=>x.kind!=='KNIFE').slice((Number(c.id.slice(1))||0)%12,(Number(c.id.slice(1))||0)%12+10).map(x=>x.name).concat('★ Karambit | Doppler');return names.map(n=>skins.find(x=>x.name===n)).filter(Boolean).map(x=>({...x,wear:'Field-Tested'}))}
function renderCases(){let q=document.getElementById('search').value.toLowerCase();let sections=[['Зимние кейсы','winter'],['Оригинальные кейсы CS2','official'],['Кастомные кейсы Downgrade','custom']];document.getElementById('case-sections').innerHTML=sections.map(([title,type])=>{let group=cases.filter(c=>c.type===type&&c.name.toLowerCase().includes(q));if(!group.length)return '';return `<div class="section-title"><h2>${title}</h2><span class="rule"></span><small>${type==='winter'?'❄ лимитированная серия':''}</small></div><div class="cases">${group.map(c=>`<article class="case-card" style="--glow:${c.color}" onclick="openCasePage('${c.id}')"><div class="case-top"><span>${type==='winter'?'Зимняя серия':type==='official'?'CS2':'Downgrade'}</span><span>✦</span></div><div class="case-art">${casePic(c)}</div><div class="case-name">${c.name}</div><div class="case-foot"><span>${type==='winter'?'Особый выбор':'Открытие кейса'}</span><span class="cost">${c.cost.toLocaleString('ru-RU')} ₽</span></div></article>`).join('')}</div>`}).join('')}
function nav(p){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id==='page-'+p));document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===p));if(p==='profile')renderInventory();if(p==='upgrade')renderUpgrade();window.scrollTo({top:0,behavior:'instant'})}document.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>nav(x.dataset.page));document.getElementById('search').oninput=renderCases;
function openCasePage(id){current=cases.find(x=>x.id===id);nav('case');renderCase()}function skinCard(i){let full=marketName(i),p=prices[full]?.price??i.price??null,img=itemImg(i);return `<article class="skin" style="--rarity:${i.kind==='KNIFE'?'#ffca6b':i.rarity==='Covert'?'#f26580':'#bd71ff'}"><div class="skin-img">${img?`<img src="${img}" alt="${full}" loading="lazy" onerror="this.remove()">`:weaponArt(i.kind)}</div><h3>${i.name}</h3><div class="skin-meta"><span>${i.rarity||'Скин'}</span><select aria-label="Износ" onchange="changeWear('${encodeURIComponent(i.name)}',this.value)">${wears.map(w=>`<option ${i.wear===w?'selected':''}>${w}</option>`).join('')}</select></div><div class="skin-price"><b>${format(p)}</b><a href="${steamLink(i)}" target="_blank" rel="noreferrer">Steam ↗</a></div></article>`}
function changeWear(encoded,w){let name=decodeURIComponent(encoded);if(current){let item=caseLoot(current).find(x=>x.name===name);if(item)item.wear=w;renderCaseLoot()}updatePrices([{name,wear:w}])}function renderCaseLoot(){document.getElementById('loot').innerHTML=caseLoot(current).map(skinCard).join('')}
