function wear(){return wears[Math.floor(Math.random()*wears.length)]}function withWear(x){return {...x,wear:wear(),float:Number((Math.random()*.78+.01).toFixed(6)),price:prices[`${x.name} (${x.wear})`]?.price??null}}
function startOpen(){if(balance<current.cost)return toast('Не хватает виртуальных рублей');if(current.type==='winter'){document.getElementById('open-message').textContent='Выбери один сугроб — внутри зимний скин';return}balance-=current.cost;document.getElementById('balance').textContent=balance.toLocaleString('ru-RU');opened++;let pool=caseLoot(current),winner=withWear(pool[Math.floor(Math.random()*pool.length)]),strip=document.getElementById('strip'),area=document.getElementById('opening');let arr=Array.from({length:36},(_,n)=>n===31?winner:withWear(pool[Math.floor(Math.random()*pool.length)]));strip.innerHTML=arr.map(x=>`<div class="strip-card">${itemImg(x)?`<img src="${itemImg(x)}">`:weaponArt(x.kind)}<b>${x.name}</b></div>`).join('');area.classList.remove('spin');document.getElementById('win').classList.remove('show');strip.style.transition='none';strip.style.transform='translateX(0)';area.classList.add('show');void area.offsetWidth;area.classList.add('spin');requestAnimationFrame(()=>{strip.style.transition='transform 5s cubic-bezier(.06,.72,.06,1)';strip.style.transform=`translateX(-${31*136-(area.clientWidth/2-64)}px)`});document.getElementById('open-message').textContent='Кейс открывается…';setTimeout(()=>{inventory.push(winner);document.getElementById('open-message').textContent=`Выпало: ${winner.name} · ${winner.wear} · float ${winner.float}`;document.getElementById('win').innerHTML=`${itemImg(winner)?`<img src="${itemImg(winner)}">`:weaponArt(winner.kind)}<h3>${winner.name}</h3><small>${winner.wear} · float ${winner.float} · ${format(winner.price)}</small>`;document.getElementById('win').classList.add('show');renderInventory();updatePrices([winner]);toast('Скин добавлен в инвентарь')},5200)}
function pickWinter(i){if(balance<current.cost)return toast('Не хватает виртуальных рублей');balance-=current.cost;document.getElementById('balance').textContent=balance.toLocaleString('ru-RU');opened++;let pool=caseLoot(current),win=withWear(pool[Math.floor(Math.random()*pool.length)]);document.querySelectorAll('.snow').forEach((x,j)=>{x.disabled=true;x.innerHTML=j===i?`🎁<span>${win.name}</span>`:'❄<span>Пусто</span>'});inventory.push(win);document.getElementById('open-message').textContent=`Нашёл: ${win.name} · ${win.wear}`;renderInventory();updatePrices([win]);toast('Зимний подарок открыт')}
function renderInventory(){let grid=document.getElementById('inventory');document.getElementById('item-count').textContent=inventory.length;document.getElementById('inventory-count').textContent=`${inventory.length} предметов`;document.getElementById('open-count').textContent=opened;let total=inventory.reduce((s,x)=>s+(x.price??prices[marketName(x)]?.price??0),0);document.getElementById('inventory-value').textContent=Math.round(total).toLocaleString('ru-RU')+' ₽';grid.innerHTML=inventory.length?inventory.map((x,i)=>`<article class="skin">${skinCard(x).replace('<article class="skin"','<div class="skin-inner"').replace('</article>','</div>')}<button class="btn secondary" onclick="sell(${i})">Продать</button></article>`).join(''):'<div class="empty">🎒<br>Инвентарь пуст. Открой кейс, чтобы получить первый скин.</div>';updatePrices(inventory)}
function sell(i){let x=inventory[i],p=x.price??prices[marketName(x)]?.price;if(!p)return toast('Для этого износа нет цены Steam');inventory.splice(i,1);balance+=p;document.getElementById('balance').textContent=balance.toLocaleString('ru-RU');renderInventory();toast(`Продано за ${format(p)}`)}
function updatePrices(items){let names=[...new Set(items.map(marketName))];if(!names.length)return;fetch('/api/prices?names='+encodeURIComponent(names.join('|'))).then(r=>r.ok?r.json():Promise.reject()).then(d=>{Object.assign(prices,d.prices||{});let stamp=d.updatedAt?new Date(d.updatedAt).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}):'сейчас';document.getElementById('price-updated').textContent=`Steam Market · обновлено ${stamp}`;let ls=document.getElementById('loot-status');if(ls)ls.textContent=`Steam Market · обновлено ${stamp}`;if(current&&document.getElementById('page-case').classList.contains('active'))renderCaseLoot();if(document.getElementById('page-profile').classList.contains('active'))renderInventory();if(document.getElementById('page-upgrade').classList.contains('active'))renderUpgrade()}).catch(()=>{let ls=document.getElementById('loot-status');if(ls)ls.textContent='Нет соединения · запусти server.js';document.getElementById('price-updated').textContent='Steam Market · сервер не запущен'})}
function renderUpgrade(){let from=document.getElementById('from-list');from.innerHTML=inventory.length?inventory.map((x,i)=>`<button class="pick ${i===fromIndex?'selected':''}" onclick="selectFrom(${i})">${itemImg(x)||weaponArt(x.kind)}<b>${x.name}</b><small>${x.wear} · ${format(x.price??prices[marketName(x)]?.price)}</small></button>`).join(''):'<div class="empty">Сначала получи предмет из кейса</div>';let targets=skins.filter(x=>x.kind!=='KNIFE').slice(0,15);document.getElementById('to-list').innerHTML=targets.map((x,i)=>`<button class="pick ${i===toIndex?'selected':''}" onclick="selectTo(${i})">${itemImg(x)||weaponArt(x.kind)}<b>${x.name}</b><small>${format(prices[`${x.name} (Field-Tested)`]?.price)} · Field-Tested</small></button>`).join('');setChance();updatePrices([...inventory,...targets.map(x=>({...x,wear:'Field-Tested'}))])}
function selectFrom(i){fromIndex=i;renderUpgrade()}function selectTo(i){toIndex=i;renderUpgrade()}function setChance(){let from=inventory[fromIndex],target=skins.filter(x=>x.kind!=='KNIFE')[toIndex],fp=from?.price??prices[marketName(from||{})]?.price,tp=target&&prices[`${target.name} (Field-Tested)`]?.price,ch=fp&&tp?Math.max(1,Math.min(94,Math.floor(fp/tp*72))):0,w=document.getElementById('wheel');w.style.setProperty('--chance',ch+'%');document.getElementById('chance').textContent=ch+'%';document.getElementById('wheel-caption').textContent=target?`Цель: ${target.name}`:'Выбери цель апгрейда';document.getElementById('wheel-note').textContent=from&&target?`Твоя ставка ${format(fp)} · цена цели ${format(tp)}`:'Зелёный сектор заполняется снизу вверх';let b=document.getElementById('upgrade');b.disabled=!(from&&target&&fp&&tp);b.textContent=from&&target?`Запустить апгрейд · ${ch}%`:'Выбрать предметы'}
document.getElementById('upgrade').onclick=()=>{let from=inventory[fromIndex],target=skins.filter(x=>x.kind!=='KNIFE')[toIndex],chance=parseInt(document.getElementById('chance').textContent);if(!from||!target||!chance)return;let w=document.getElementById('wheel');w.style.transform='rotate(1440deg)';setTimeout(()=>{w.style.transform='';if(Math.random()*100<chance){inventory.splice(fromIndex,1);inventory.push({...target,wear:'Field-Tested',float:.21,price:prices[`${target.name} (Field-Tested)`]?.price});toast('Апгрейд успешен')}else{inventory.splice(fromIndex,1);toast('Апгрейд не прошёл')};fromIndex=toIndex=null;renderInventory();renderUpgrade()},4000)};
