function ensureIcon(name){if(!name||icons[name]||iconRequests.has(name))return;iconRequests.add(name);fetch('/api/icon?name='+encodeURIComponent(name)).then(r=>r.ok?r.json():null).then(d=>{if(!d?.url)return;icons[name]=d.url;let page=document.querySelector('.page.active')?.id;if(page==='page-cases')renderCases();if(page==='page-case'&&current){document.querySelector('.detail-art').innerHTML=casePic(current);renderCaseLoot()}if(page==='page-profile')renderInventory();if(page==='page-upgrade')renderUpgrade()}).catch(()=>{}).finally(()=>iconRequests.delete(name))}
function casePic(c){if(c.name==='Kilowatt Case')return `<img src="${imageMap[c.name]}" alt="Kilowatt Case">`;if(c.type==='official'){if(icons[c.name])return `<img src="${icons[c.name]}" alt="${c.name}">`;ensureIcon(c.name)}return boxArt(c.color,c.id.replace(/\W/g,''))}
function caseLoot(c){let names=casePools[c.name]||skins.filter(x=>x.kind!=='KNIFE').slice((Number(c.id.slice(1))||0)%12,(Number(c.id.slice(1))||0)%12+10).map(x=>x.name).concat('★ Karambit | Doppler');return names.map(n=>skins.find(x=>x.name===n)).filter(Boolean).map(x=>({...x,wear:wearChoice[x.name]||'Field-Tested'}))}
function changeWear(encoded,w){let name=decodeURIComponent(encoded);wearChoice[name]=w;if(current)renderCaseLoot();updatePrices([{name,wear:w}])}
function nav(p){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id==='page-'+p));document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===p));if(p==='profile'){renderInventory();updatePrices(inventory)}if(p==='upgrade'){renderUpgrade();updatePrices([...inventory,...skins.filter(x=>x.kind!=='KNIFE').slice(0,15).map(x=>({...x,wear:'Field-Tested'}))])}window.scrollTo({top:0,behavior:'instant'})}
function renderInventory(){let grid=document.getElementById('inventory');document.getElementById('item-count').textContent=inventory.length;document.getElementById('inventory-count').textContent=`${inventory.length} предметов`;document.getElementById('open-count').textContent=opened;let total=inventory.reduce((s,x)=>s+(x.price??prices[marketName(x)]?.price??0),0);document.getElementById('inventory-value').textContent=Math.round(total).toLocaleString('ru-RU')+' ₽';grid.innerHTML=inventory.length?inventory.map((x,i)=>`<article class="skin">${skinCard(x).replace('<article class="skin"','<div class="inner"').replace('</article>','</div>')}<button class="btn secondary" onclick="sell(${i})">Продать</button></article>`).join(''):'<div class="empty">🎒<br>Инвентарь пуст. Открой кейс, чтобы получить первый скин.</div>'}
function renderUpgrade(){let from=document.getElementById('from-list');from.innerHTML=inventory.length?inventory.map((x,i)=>`<button class="pick ${i===fromIndex?'selected':''}" onclick="selectFrom(${i})">${itemImg(x)||weaponArt(x.kind)}<b>${x.name}</b><small>${x.wear} · ${format(x.price??prices[marketName(x)]?.price)}</small></button>`).join(''):'<div class="empty">Сначала получи предмет из кейса</div>';let targets=skins.filter(x=>x.kind!=='KNIFE').slice(0,15);document.getElementById('to-list').innerHTML=targets.map((x,i)=>`<button class="pick ${i===toIndex?'selected':''}" onclick="selectTo(${i})">${itemImg(x)||weaponArt(x.kind)}<b>${x.name}</b><small>${format(prices[`${x.name} (Field-Tested)`]?.price)} · Field-Tested</small></button>`).join('');setChance()}
function updatePrices(items){let names=[...new Set(items.map(marketName))];if(!names.length)return;fetch('/api/prices?names='+encodeURIComponent(names.join('|'))).then(r=>r.ok?r.json():Promise.reject()).then(d=>{Object.assign(prices,d.prices||{});inventory.forEach(x=>{x.price=prices[marketName(x)]?.price??x.price});let stamp=d.updatedAt?new Date(d.updatedAt).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}):'сейчас';document.getElementById('price-updated').textContent=`Steam Market · обновлено ${stamp}`;let ls=document.getElementById('loot-status');if(ls)ls.textContent=`Steam Market · обновлено ${stamp}`;let page=document.querySelector('.page.active')?.id;if(page==='page-case')renderCaseLoot();if(page==='page-profile')renderInventory();if(page==='page-upgrade')renderUpgrade()}).catch(()=>{let ls=document.getElementById('loot-status');if(ls)ls.textContent='Steam Market недоступен · открой сайт через server.js';document.getElementById('price-updated').textContent='Steam Market · сервер не запущен'})}
