function caseLoot(c){let names=casePools[c.name]||skins.filter(x=>x.kind!=='KNIFE').slice((Number(c.id.slice(1))||0)%12,(Number(c.id.slice(1))||0)%12+10).map(x=>x.name);return names.map(n=>{let found=skins.find(x=>x.name===n);let weapon=n.split(' | ')[0];let kind=weapon==='AK-47'?'AK':weapon.startsWith('M4')?'M4':weapon.startsWith('AWP')?'AWP':weapon.startsWith('MP')?'MP9':weapon.startsWith('USP')?'USP':weapon.startsWith('Glock')?'GL':weapon.includes('Desert Eagle')?'DE':weapon.includes('P250')?'P250':weapon.startsWith('★')?'KNIFE':'RIFLE';return {...(found||{name:n,kind,rarity:'CS2 skin'}),wear:wearChoice[n]||'Field-Tested'}})}
