function marketName(i){return i.name+' ('+(i.kind==='KNIFE'?'Factory New':'Field-Tested')+')'}
function steamLink(i){return steamBase+encodeURIComponent(marketName(i))}
function withWear(x){const wear=x.kind==='KNIFE'?'Factory New':'Field-Tested';return {...x,wear,float:.2,price:prices[marketName({...x,wear})]?.price??null}}
var iconQueueNames=window.iconQueueNames=window.iconQueueNames||[];var iconBusy=window.iconBusy=window.iconBusy||0;
function itemImg(i){let u=i.img||imageMap[i.name]||icons[i.name]||'';if(!u)ensureIcon(i.name);return u}
function casePic(c){if(imageMap[c.name])return '<img src="'+imageMap[c.name]+'" alt="'+c.name+'" loading="lazy">';if(c.type==='official'){if(icons[c.name])return '<img src="'+icons[c.name]+'" alt="'+c.name+'" loading="lazy">';ensureIcon(c.name)}return boxArt(c.color,c.id.replace(/\W/g,''))}
function ensureIcon(name){window.iconQueueNames=window.iconQueueNames||[];if(!Number.isFinite(window.iconBusy))window.iconBusy=0;if(!name||icons[name]||iconRequests.has(name))return;iconRequests.add(name);window.iconQueueNames.push(name);pumpIcons()}
function pumpIcons(){while(window.iconBusy<6&&window.iconQueueNames.length){const name=window.iconQueueNames.shift();window.iconBusy++;fetch('/api/icon?name='+encodeURIComponent(name)).then(r=>r.ok?r.json():null).then(d=>{if(!d?.url)return;icons[name]=d.url;const page=document.querySelector('.page.active')?.id;if(page==='page-cases')renderCases();if(page==='page-case'&&current){document.querySelector('.detail-art').innerHTML=casePic(current);renderCaseLoot()}if(page==='page-profile')renderInventory();if(page==='page-upgrade')renderUpgrade(false)}).catch(()=>{}).finally(()=>{iconRequests.delete(name);window.iconBusy--;pumpIcons()})}}
function skinCard(i,mode='loot'){const key=marketName(i),p=prices[key]?.price??i.price??null,img=itemImg(i),button=mode==='inventory'?'<button class="sell-inline" onclick="sell('+inventory.indexOf(i)+')">Продать</button>':'';return '<article class="skin" style="--rarity:'+(i.kind==='KNIFE'?'#ffca6b':i.rarity==='Covert'?'#f26580':'#bd71ff')+'"><div class="skin-img">'+(img?'<img src="'+img+'" alt="'+i.name+'" loading="lazy">':weaponArt(i.kind))+'</div><h3>'+i.name+'</h3><div class="skin-meta"><span>'+(i.rarity||'Скин')+'</span></div><div class="skin-price"><b>'+format(p)+'</b>'+button+'<a href="'+steamLink(i)+'" target="_blank" rel="noreferrer">Steam ↗</a></div></article>'}
function renderInventory(){const grid=document.getElementById('inventory');document.getElementById('item-count').textContent=inventory.length;document.getElementById('inventory-count').textContent=inventory.length+' предметов';document.getElementById('open-count').textContent=opened;const total=inventory.reduce((s,x)=>s+(prices[marketName(x)]?.price??x.price??0),0);document.getElementById('inventory-value').textContent=Math.round(total).toLocaleString('ru-RU')+' ₽';grid.innerHTML=inventory.length?inventory.map(x=>skinCard(x,'inventory')).join(''):'<div class="empty">🎒<br>Инвентарь пуст. Открой кейс, чтобы получить первый скин.</div>';persist()}
function updatePrices(items){const names=[...new Set(items.map(marketName))];if(!names.length)return;fetch('/api/prices?names='+encodeURIComponent(names.join('~'))).then(r=>r.ok?r.json():Promise.reject()).then(d=>{Object.assign(prices,d.prices||{});inventory.forEach(x=>{x.price=prices[marketName(x)]?.price??null});const stamp=d.updatedAt?new Date(d.updatedAt).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}):'сейчас',label=document.getElementById('price-updated'),status=document.getElementById('loot-status');if(label)label.textContent='Steam Market · обновлено '+stamp;if(status)status.textContent='Steam Market · обновлено '+stamp;if(document.getElementById('page-case').classList.contains('active'))renderCaseLoot();if(document.getElementById('page-profile').classList.contains('active'))renderInventory();if(document.getElementById('page-upgrade').classList.contains('active')){renderUpgrade(false);setChance()}}).catch(()=>{const status=document.getElementById('loot-status');if(status)status.textContent='Цены Steam Market временно недоступны'})}
function renderUpgrade(loadPrices=true){const from=document.getElementById('from-list'),targets=skins.filter(x=>x.kind!=='KNIFE').slice(0,15);from.innerHTML=inventory.length?inventory.map((x,i)=>{const img=itemImg(x);return '<button class="pick '+(i===fromIndex?'selected':'')+'" onclick="selectFrom('+i+')">'+(img?'<img src="'+img+'" alt="'+x.name+'" loading="lazy">':weaponArt(x.kind))+'<b>'+x.name+'</b><small>'+format(prices[marketName(x)]?.price??x.price)+'</small></button>'}).join(''):'<div class="empty">Сначала получи предмет из кейса</div>';document.getElementById('to-list').innerHTML=targets.map((x,i)=>{const img=itemImg(x);return '<button class="pick '+(i===toIndex?'selected':'')+'" onclick="selectTo('+i+')">'+(img?'<img src="'+img+'" alt="'+x.name+'" loading="lazy">':weaponArt(x.kind))+'<b>'+x.name+'</b><small>'+format(prices[marketName(x)]?.price)+'</small></button>'}).join('');setChance();if(loadPrices)updatePrices([...inventory,...targets])}
function setChance(){const from=inventory[fromIndex],target=skins.filter(x=>x.kind!=='KNIFE')[toIndex],fp=from&&(prices[marketName(from)]?.price??from.price),tp=target&&prices[marketName(target)]?.price,ready=Number.isFinite(fp)&&fp>0&&Number.isFinite(tp)&&tp>0,ch=ready?Math.max(1,Math.min(94,Math.floor(fp/tp*72))):0,wheel=document.getElementById('wheel');wheel.style.setProperty('--chance',ch+'%');document.getElementById('chance').textContent=ready?ch+'%':'—';document.getElementById('wheel-caption').textContent=target?'Цель: '+target.name:'Выбери цель апгрейда';document.getElementById('wheel-note').textContent=from&&target?(ready?'Твоя ставка '+format(fp)+' · цена цели '+format(tp):'Загружаем цены Steam Market…'):'Зелёный сектор показывает шанс успеха';const button=document.getElementById('upgrade');button.disabled=!(from&&target&&ready);button.textContent=from&&target?(ready?'Запустить апгрейд · '+ch+'%':'Загружаем цены…'):'Выбрать предметы'}
document.getElementById('upgrade').onclick=()=>{const target=skins.filter(x=>x.kind!=='KNIFE')[toIndex],chance=parseInt(document.getElementById('chance').textContent);if(fromIndex===null||!target||!chance)return;if(Math.random()*100<chance){inventory.splice(fromIndex,1);inventory.push({...target,wear:'Field-Tested',float:.2,price:prices[marketName(target)]?.price??null});toast('Апгрейд успешен')}else{inventory.splice(fromIndex,1);toast('Апгрейд не прошёл')}fromIndex=toIndex=null;renderInventory();renderUpgrade()}
function sell(i){const x=inventory[i],p=prices[marketName(x)]?.price??x.price;if(!Number.isFinite(p)||p<=0)return toast('Цена Steam Market пока не загрузилась');inventory.splice(i,1);balance+=p;document.getElementById('balance').textContent=balance.toLocaleString('ru-RU');renderInventory();toast('Продано за '+format(p))}
