function renderCaseLoot(){if(!current)return;const pool=ensureCaseDrops(current),grid=document.getElementById('loot'),status=document.getElementById('loot-status'),button=document.querySelector('.detail-actions .btn'),pending=caseExpansionPending.has(current.id);if(grid)grid.innerHTML=pool.map(item=>skinCard(item)).join('')||'<div class="empty">Подбираем скины с ценой выше 15% стоимости кейса…</div>';if(status)status.textContent=pending?'Подбираем цены и дропы выше 15% цены кейса…':pool.length+' возможных предметов · каждый не дешевле 15% цены кейса';if(button)button.disabled=!pool.length||pending}
function dropWeight(item,cost){const price=caseMarketPrice(item);if(price<cost*.15)return 0;return Math.min(1,Math.pow((cost*3)/Math.max(price,cost*.15),.68))}
function weightedDrop(pool,cost){const eligible=pool.filter(item=>caseMarketPrice(item)>=cost*.15);if(!eligible.length)return null;const weights=eligible.map(item=>dropWeight(item,cost)),total=weights.reduce((a,b)=>a+b,0);let cursor=Math.random()*total;for(let i=0;i<eligible.length;i++){cursor-=weights[i];if(cursor<=0)return withWear(eligible[i])}return withWear(eligible[eligible.length-1])}
function casePriceSource(item){const q=prices[marketName(item)];return q?.estimated?'Оценка Skinport':q?.source==='Steam Community Market'?'Steam Market':q?.source||'Рыночная цена'}
function sellCaseDrop(){if(!lastCaseDrop)return;const index=inventory.indexOf(lastCaseDrop);if(index<0)return;const value=caseMarketPrice(lastCaseDrop);sell(index);document.getElementById('open-message').textContent='Продано за '+format(value);document.getElementById('opening').classList.remove('finished','show');lastCaseDrop=null}
function upgradeCaseDrop(){if(!lastCaseDrop)return;fromIndex=inventory.indexOf(lastCaseDrop);toIndex=null;priceFilters.chance=null;nav('upgrade');mobileTab('to')}
function startOpen(){if(caseOpening||!current||balance<current.cost)return toast(caseOpening?'Кейс уже открывается':'Не хватает виртуальных рублей');if(current.type==='winter'){document.getElementById('open-message').textContent='Выбери один сугроб — внутри зимний скин';return}const pool=ensureCaseDrops(current);if(caseExpansionPending.has(current.id)||!pool.length)return toast('Подбираю цены и предметы для кейса');const winner=weightedDrop(pool,current.cost);if(!winner)return toast('Нет предметов с загруженной ценой выше 15% цены кейса');caseOpening=true;balance-=current.cost;document.getElementById('balance').textContent=balance.toLocaleString('ru-RU');opened++;const strip=document.getElementById('strip'),area=document.getElementById('opening'),win=document.getElementById('win'),openButton=document.querySelector('.detail-actions .btn'),resultIndex=34;const items=Array.from({length:38},(_,i)=>i===resultIndex?winner:withWear(pool[Math.floor(Math.random()*pool.length)]));strip.innerHTML=items.map(item=>{const img=itemImg(item);return '<div class="strip-card">'+(img?'<img src="'+img+'" alt="'+item.name+'">':weaponArt(item.kind))+'<b>'+item.name+'</b></div>'}).join('');win.classList.remove('show');win.innerHTML='';area.classList.remove('finished','spin');area.classList.add('show');strip.style.transition='none';strip.style.transform='translateX(0)';void area.offsetWidth;if(openButton)openButton.disabled=true;document.getElementById('open-message').textContent='Крутится…';requestAnimationFrame(()=>{const card=strip.children[resultIndex],distance=card.offsetLeft+card.offsetWidth/2-area.clientWidth/2;strip.style.transition='transform 10.4s cubic-bezier(.28,.18,.18,1)';strip.style.transform='translateX(-'+distance+'px)';area.classList.add('spin')});setTimeout(()=>{caseOpening=false;lastCaseDrop=winner;inventory.push(winner);const value=caseMarketPrice(winner),wear=winner.wear||'Field-Tested',float=Number.isFinite(winner.float)?winner.float.toFixed(4):'—',img=itemImg(winner);win.innerHTML='<img class="result-image" src="'+(img||'')+'" alt="'+winner.name+'"><div class="result-info"><small>КЕЙС ОТКРЫТ · '+(winner.rarity||'СКИН')+'</small><h3>'+winner.name+'</h3><p>'+wear+' · float '+float+'</p><b>'+format(value)+'</b><small class="quote-source">'+casePriceSource(winner)+'</small><div class="result-actions"><button class="btn" onclick="sellCaseDrop()">Продать</button><button class="btn ghost" onclick="upgradeCaseDrop()">В апгрейд</button></div></div>';win.classList.add('show');area.classList.remove('spin');area.classList.add('finished');document.getElementById('open-message').textContent='Предмет добавлен в инвентарь';renderInventory();if(openButton)openButton.disabled=false},10650)}
function pickWinter(i){if(caseOpening||!current||current.type!=='winter')return;if(caseExpansionPending.has(current.id))return toast('Подбираю цены и дропы для зимнего кейса');if(balance<current.cost)return toast('Не хватает виртуальных рублей');const pool=ensureCaseDrops(current),buttons=[...document.querySelectorAll('.snow')],chosen=buttons[i];if(!chosen||!pool.length)return toast('Загружаю цены зимнего кейса');caseOpening=true;balance-=current.cost;document.getElementById('balance').textContent=balance.toLocaleString('ru-RU');opened++;buttons.forEach((button,j)=>{button.disabled=true;button.classList.toggle('digging',j===i);if(j!==i)button.classList.add('empty-snow')});chosen.innerHTML='❄<span>Раскапываем…</span>';const winner=weightedDrop(pool,current.cost);if(!winner){caseOpening=false;return toast('Нет скинов выше 15% цены кейса')}document.getElementById('open-message').textContent='Сугроб раскрывается…';setTimeout(()=>{caseOpening=false;chosen.classList.remove('digging');chosen.classList.add('found-snow');chosen.innerHTML='🎁<span>'+winner.name+'</span>';buttons.forEach((button,j)=>{if(j!==i)button.innerHTML='❄<span>Пусто</span>'});lastCaseDrop=winner;inventory.push(winner);renderInventory();document.getElementById('open-message').textContent='Нашёл: '+winner.name;toast('Зимний подарок открыт')},850)}
