try{const saved=JSON.parse(localStorage.getItem(stateStorageKey)||'null');if(saved&&saved.balanceVersion!==1){balance=500;saved.balance=500;saved.balanceVersion=1;localStorage.setItem(stateStorageKey,JSON.stringify(saved))}}catch{}
const persistWithStartingBalance=persist;
persist=function(){persistWithStartingBalance();try{const saved=JSON.parse(localStorage.getItem(stateStorageKey)||'{}');saved.balanceVersion=1;localStorage.setItem(stateStorageKey,JSON.stringify(saved))}catch{}}
